import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import UploadZone from './components/UploadZone';
import AvatarCards from './components/AvatarCards';
import VoicePanel from './components/VoicePanel';
import RecentSummaries from './components/RecentSummaries';
import HistorySidebar from './components/HistorySidebar';
import SettingsModal from './components/SettingsModal';
import Header from './components/Header';
import { useTheme } from './hooks/useTheme';
import { useSettings } from './hooks/useSettings';

function App() {
  const [selectedAvatar, setSelectedAvatar] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentDocument, setCurrentDocument] = useState(null);
  const [recentSummaries, setRecentSummaries] = useState([]);
  const [history, setHistory] = useState([]);
  const [showSettings, setShowSettings] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const { theme, toggleTheme } = useTheme();
  const { settings, updateSettings } = useSettings();

  // Load initial data from localStorage
  useEffect(() => {
    const savedSummaries = localStorage.getItem('recentSummaries');
    const savedHistory = localStorage.getItem('documentHistory');
    
    if (savedSummaries) {
      setRecentSummaries(JSON.parse(savedSummaries));
    }
    
    if (savedHistory) {
      setHistory(JSON.parse(savedHistory));
    }
  }, []);

  // Save data to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('recentSummaries', JSON.stringify(recentSummaries));
  }, [recentSummaries]);

  useEffect(() => {
    localStorage.setItem('documentHistory', JSON.stringify(history));
  }, [history]);

  const handleDocumentUpload = (document) => {
    setCurrentDocument(document);
    const newHistoryItem = {
      id: Date.now(),
      name: document.name,
      type: document.type,
      size: document.size,
      timestamp: new Date().toISOString(),
      avatar: null,
      summary: null
    };
    setHistory(prev => [newHistoryItem, ...prev]);
  };

  const handleAvatarSelect = (avatar) => {
    setSelectedAvatar(avatar);
    setIsProcessing(true);
    
    // Simulate processing
    setTimeout(() => {
      setIsProcessing(false);
      
      // Create summary
      const summary = {
        id: Date.now(),
        documentId: currentDocument?.id,
        avatar: avatar.name,
        content: `This is a ${avatar.name.toLowerCase()} summary of the document...`,
        timestamp: new Date().toISOString(),
        duration: Math.floor(Math.random() * 300) + 60 // 1-5 minutes
      };
      
      setRecentSummaries(prev => [summary, ...prev.slice(0, 9)]); // Keep only 10 most recent
      
      // Update history
      if (currentDocument) {
        setHistory(prev => 
          prev.map(item => 
            item.id === currentDocument.id 
              ? { ...item, avatar: avatar.name, summary: summary.id }
              : item
          )
        );
      }
    }, 2000);
  };

  const handleVoiceControl = (action) => {
    console.log('Voice control action:', action);
  };

  return (
    <div className={`min-h-screen transition-colors duration-300 ${theme === 'dark' ? 'dark' : ''}`}>
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-900 dark:to-blue-900">
        <Header 
          onSettingsClick={() => setShowSettings(true)}
          onHistoryClick={() => setShowHistory(!showHistory)}
          theme={theme}
          toggleTheme={toggleTheme}
        />
        
        <main className="container mx-auto px-4 py-8">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Main Content Area */}
            <div className="lg:col-span-2 space-y-8">
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6 }}
              >
                <UploadZone onDocumentUpload={handleDocumentUpload} />
              </motion.div>
              
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: 0.2 }}
              >
                <AvatarCards
                  selectedAvatar={selectedAvatar}
                  onAvatarSelect={handleAvatarSelect}
                  isProcessing={isProcessing}
                  disabled={!currentDocument}
                />
              </motion.div>
              
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: 0.4 }}
              >
                <RecentSummaries 
                  summaries={recentSummaries}
                  onSummaryClick={(summary) => console.log('Summary clicked:', summary)}
                />
              </motion.div>
            </div>
            
            {/* Sidebar */}
            <div className="lg:col-span-1">
              <AnimatePresence>
                {showHistory && (
                  <motion.div
                    initial={{ opacity: 0, x: 300 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 300 }}
                    transition={{ duration: 0.3 }}
                  >
                    <HistorySidebar 
                      history={history}
                      onItemClick={(item) => console.log('History item clicked:', item)}
                    />
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </main>
        
        {/* Voice Panel */}
        <AnimatePresence>
          {selectedAvatar && (
            <VoicePanel
              avatar={selectedAvatar}
              isProcessing={isProcessing}
              onVoiceControl={handleVoiceControl}
              onClose={() => setSelectedAvatar(null)}
            />
          )}
        </AnimatePresence>
        
        {/* Settings Modal */}
        <AnimatePresence>
          {showSettings && (
            <SettingsModal
              settings={settings}
              onUpdateSettings={updateSettings}
              onClose={() => setShowSettings(false)}
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

export default App;
